# payment_service.py - PG 결제 처리

from pg_client import PGClient

# PGClient는 PR #148에서 v3로 업그레이드됨
pg_client = PGClient(api_version="v3", api_key=os.environ["PG_API_KEY"])

def create_payment(order_id: str, amount: int, payment_method: str) -> Payment:
    """결제 생성. PG API v3 사용."""
    return pg_client.create_charge(order_id, amount, payment_method)

def get_payment(payment_id: str) -> Payment:
    return pg_client.get_charge(payment_id)

