# refund_service.py - 환불 처리 (PR #152에서 부분환불 추가)

from enum import Enum

class RefundStatus(Enum):
    REQUESTED = "REQUESTED"
    DONE = "DONE"
    PARTIAL_REFUND = "PARTIAL_REFUND"  # PR #152에서 추가
    REFUND_FAILED = "REFUND_FAILED"

class RefundService:
    def __init__(self, pg_client):
        self.pg_client = pg_client  # PG API v3 사용

    def refund(self, payment_id: str, amount: int, idempotency_key: str) -> Refund:
        """전체 환불."""
        # ... 기존 로직
        return Refund(status=RefundStatus.DONE)

    def partial_refund(self, payment_id: str, amount: int, idempotency_key: str) -> Refund:
        """부분환불. PR #152에서 추가."""
        # 기존 환불 트랜잭션과 idempotency 유지
        # PG API v3의 부분환불 endpoint 사용
        refund = self.pg_client.partial_refund(payment_id, amount, idempotency_key)
        return Refund(status=RefundStatus.PARTIAL_REFUND, amount=amount)

    # 주의: 해외결제 부분환불은 아직 정책 정의되지 않음.
    # pg_client.partial_refund()는 호출 가능하지만,
    # 해외결제에 대한 비즈니스 정책은 별도로 확인 필요.
